class Solution {
    private int[][] grid;
    private Integer[][][] memo;
    private int n;
    public int cherryPickup(int[][] grid){
        this.grid=grid;
        n=grid.length;
        memo=new Integer[n][n][n];
        return Math.max(0,dfs(0,0,0));
    }
    private int dfs(int r1,int c1,int r2){
        int c2=r1+c1-r2;
        if(r1>=n||c1>=n||r2>=n||c2<0||c2>=n||grid[r1][c1]==-1||grid[r2][c2]==-1)return -1000000;
        if(r1==n-1&&c1==n-1)return grid[r1][c1];
        if(memo[r1][c1][r2]!=null)return memo[r1][c1][r2];
        int cherries=grid[r1][c1]+(r1==r2&&c1==c2?0:grid[r2][c2]);
        int next=Math.max(Math.max(dfs(r1+1,c1,r2+1),dfs(r1+1,c1,r2)),Math.max(dfs(r1,c1+1,r2+1),dfs(r1,c1+1,r2)));
        return memo[r1][c1][r2]=cherries+next;
    }
}

