class Solution {
    private lateinit var grid:Array<IntArray>;
    private lateinit var memo:Array<Array<Array<Int?>>>;
    private var n=0;
    fun cherryPickup(grid:Array<IntArray>):Int{
        this.grid=grid;
        n=grid.size;
        memo=Array(n){
            Array(n){
                arrayOfNulls<Int>(n)
            }
        };
        return maxOf(0,dfs(0,0,0))
    };
    private fun dfs(r1:Int,c1:Int,r2:Int):Int{
        val c2=r1+c1-r2;
        if(r1>=n||c1>=n||r2>=n||c2 !in 0 until n||grid[r1][c1]==-1||grid[r2][c2]==-1)return -1000000;
        if(r1==n-1&&c1==n-1)return grid[r1][c1];
        memo[r1][c1][r2]?.let{
            return it
        };
        val cherries=grid[r1][c1]+if(r1==r2&&c1==c2)0 else grid[r2][c2];
        val next=maxOf(dfs(r1+1,c1,r2+1),dfs(r1+1,c1,r2),dfs(r1,c1+1,r2+1),dfs(r1,c1+1,r2));
        return(cherries+next).also{
            memo[r1][c1][r2]=it
        }
    }
}

