class Solution {
    vector<vector<int>> grid;
    vector<vector<vector<int>>> memo;
    int n;
    int dfs(int r1,int c1,int r2){
        int c2=r1+c1-r2;
        if(r1>=n||c1>=n||r2>=n||c2<0||c2>=n||grid[r1][c1]==-1||grid[r2][c2]==-1)return -1000000;
        if(r1==n-1&&c1==n-1)return grid[r1][c1];
        int& result=memo[r1][c1][r2];
        if(result!=INT_MIN)return result;
        int cherries=grid[r1][c1]+(r1==r2&&c1==c2?0:grid[r2][c2]);
        int next=max({
            dfs(r1+1,c1,r2+1),dfs(r1+1,c1,r2),dfs(r1,c1+1,r2+1),dfs(r1,c1+1,r2)
        });
        return result=cherries+next;
    }
    public:int cherryPickup(vector<vector<int>>& value){
        grid=value;
        n=grid.size();
        memo.assign(n,vector<vector<int>>(n,vector<int>(n,INT_MIN)));
        return max(0,dfs(0,0,0));
    }
};
